  await page.waitForTimeout(2000);
  const title = await page.title();
  const body = await page.textContent('body');
  console.log('TITLE', title);
  console.log('BODY_LEN', body.length);
  console.log('HAS_CANVAS', await page.locator('#battleCanvas').count());
  console.log('BTN_COUNT', await page.locator('button').count());
  const ready = await page.evaluate(() => ({
    hasCanvas: !!document.getElementById('battleCanvas'),
    hasStatePill: !!document.getElementById('statePill'),
    countChars: (window.characters || []).length,
    battleState: document.getElementById('battleState')?.textContent,
    errors: []
  }));
  console.log(JSON.stringify(ready,null,2));
  await browser.close();
})();
